// Auto-generated embedded base64 of the complete, verified Browser Extension ZIP package
export const EMBEDDED_EXTENSION_ZIP_BASE64 = '';

export function getEmbeddedExtensionZipBlob(): Blob {
  const binaryString = atob(EMBEDDED_EXTENSION_ZIP_BASE64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return new Blob([bytes], { type: 'application/zip' });
}
